    const premium=makeLink('/membership','');premium.className='dropso-redesign-premium';premium.setAttribute('aria-label','DROPSO PREMIUM');premium.title='DROPSO PREMIUM';premium.append(makeIcon('premium'));const label=document.createElement('span');label.className='dropso-menu-label';label.textContent='DROPSO PREMIUM';premium.append(label);const arrow=document.createElement('span');arrow.className='dropso-premium-arrow';arrow.textContent='›';premium.append(arrow);if(location.pathname==='/membership')premium.setAttribute('aria-current','page');if(nav)nav.before(premium);
